import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.2af478d7.js";const p=JSON.parse('{"title":"ADR index","description":"","frontmatter":{},"headers":[],"relativePath":"adr/index.md","filePath":"adr/index.md"}'),c={name:"adr/index.md"};function d(n,e,i,h,s,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-index" tabindex="-1">ADR index <a class="header-anchor" href="#adr-index" aria-label="Permalink to &quot;ADR index&quot;">​</a></h1><p>Architecture decision records explain why the package works the way it does. Each record keeps its original text and gains a dated update note when the code changes names or details. Read a record before you propose a change to the area it covers.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Know the terms <a href="./../vocabulary#content-generation">content generation</a>, <a href="./../vocabulary#native-collection">native collection</a> and <a href="./../vocabulary#search-backend">search backend</a>.</p><h2 id="records" tabindex="-1">Records <a class="header-anchor" href="#records" aria-label="Permalink to &quot;Records&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Record</th><th>Status</th><th>Decision</th><th>Read with</th></tr></thead><tbody><tr><td><a href="./0001-content-cache-with-generation-key">0001. Content cache keyed by a global generation, invalidated by webhook</a></td><td>Accepted</td><td>Cache decoded JSON:API documents with stale-while-revalidate. Put a content generation in every key and replace it from a signed webhook or <code>drupal:flush</code>.</td><td><a href="./../caching-model">Caching model</a>, <a href="./../webhook-and-cache-flushing">Webhook and cache flushing</a></td></tr><tr><td><a href="./0002-search-on-native-collections-with-index-for-flags">0002. Typed terms search the native collections; the index serves filters and flags</a></td><td>Accepted</td><td>Match a typed term on the native collections so partial words work. Since 3.0.0 the index is an optional extension that serves filters, flags and exact totals.</td><td><a href="./../search-setup">Search setup</a></td></tr></tbody></table><h2 id="update-notes" tabindex="-1">Update notes <a class="header-anchor" href="#update-notes" aria-label="Permalink to &quot;Update notes&quot;">​</a></h2><p>The records keep their history, so the body text can name classes that no longer exist. The update note at the end of each record gives the current names.</p><h3 id="_0001-cache-generation" tabindex="-1">0001: cache generation <a class="header-anchor" href="#_0001-cache-generation" aria-label="Permalink to &quot;0001: cache generation&quot;">​</a></h3><ul><li>The generation is per Source, not global: keys are <code>drupal:{source}:{generation}:{hash}</code>. The addendum in the record introduced this.</li><li><code>DrupalManager</code> hands out one <code>CachedDrupal</code> per Source and follows <code>flush.also.sources</code> when it flushes.</li><li>The cache windows ship as defaults in the package&#39;s <code>config/drupal.php</code>.</li><li><code>drupal:contract</code> specifies the webhook sender.</li></ul><h3 id="_0002-search" tabindex="-1">0002: search <a class="header-anchor" href="#_0002-search" aria-label="Permalink to &quot;0002: search&quot;">​</a></h3><ul><li><code>SearchFetcher</code> replaces <code>SearchFetchService</code>, with <code>SearchTabs</code>, <code>SearchSorts</code>, <code>SearchFilterSet</code> and <code>SearchQueries</code>.</li><li>The relevance weights are the <code>term_fields</code> and <code>related_term_fields</code> of each searchable content type.</li><li>The match strategy is a setting: <code>native_contains</code> is this record&#39;s decision and the default, and <code>index_fulltext</code> suits a backend whose index matches partial words.</li><li>Since 2.0.0 any number of types are searchable; the strategy and the index lookup are per type, and filters and sorts apply on their own type&#39;s tab.</li><li>Since 3.0.0 core searches native collections only, behind the <code>SearchBackend</code> seam. The index moved to <code>proteo/drupal-search-api</code>; counts carry an <code>exact</code> flag and filter-only searches page natively.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Understand the cache in the <a href="./../caching-model">Caching model</a>.</li><li>Set up search in <a href="./../search-setup">Search setup</a>.</li><li>Read the package vocabulary in <a href="./../vocabulary">Vocabulary</a>.</li></ul>',14)])])}const f=a(c,[["render",d]]);export{p as __pageData,f as default};
